const blankProduct=():Product=>({id:id('product'),name:'',game:'Roblox',category:'Item',sku:'',supplier:'',stock:0,reorderPoint:5,modal:0,price:0,fee:10,fixed:0,other:0,target:20,stockSince:new Date().toISOString(),discountEnabled:false,discountPrice:0,active:true,updatedAt:undefined})
