type Ctx=any

function QuickActions({setActive}:Ctx){return <div className="flex flex-wrap gap-2"><button onClick={()=>setActive('Quick Order')} className="btn-primary">+ Buat Order</button><button onClick={()=>setActive('Restock')} className="btn-secondary">+ Restock</button><button onClick={()=>setActive('Action Center')} className="btn-secondary">Pusat Aksi</button></div>}

function ActionNeededPanel({products,orders,settlements,disputes,targets,setActive}:Ctx){
  const items=useMemo(()=>actionCenter(products,orders,settlements,disputes,targets).slice(0,8),[products,orders,settlements,disputes,targets])
  return <Card title="Perlu Tindakan" subtitle="Prioritas otomatis lintas modul: stok kritis, margin bocor, settlement, dispute, order terlambat, dan target berisiko." action={<button onClick={()=>setActive('Action Center')} className="text-xs font-bold text-primary">Buka Action Center →</button>}>
    <div className="grid gap-2 lg:grid-cols-2">{items.map((x:any)=><button key={x.id} onClick={()=>setActive(x.target)} className="rounded-xl border p-3 text-left transition hover:bg-muted/40"><div className="flex items-center justify-between gap-2"><strong className="text-sm">{x.title}</strong><div className="flex gap-1"><Badge tone={x.priority==='P1'?'red':x.priority==='P2'?'amber':'blue'}>{x.priority}</Badge><Badge>{x.category}</Badge></div></div><p className="mt-1.5 text-xs text-muted-foreground">{x.detail}</p>{x.impact>0&&<p className="mt-1.5 text-xs font-bold">Impact: {money(x.impact)}</p>}</button>)}</div>
    {!items.length&&<Empty text="Semua aman — tidak ada tindakan prioritas saat ini."/>}
  </Card>
}

function Dashboard({products,orders,expenses,targets,setActive}:Ctx){
  const totals=useMemo(()=>{const today=new Date();today.setHours(0,0,0,0);const month=new Date();month.setDate(1);month.setHours(0,0,0,0);const now=new Date();return {t:businessTotals(orders,expenses,today,now),m:businessTotals(orders,expenses,month,now)}},[orders,expenses])
  const alerts=useMemo(()=>deriveAlerts(products,orders),[products,orders])
  const t=totals.t,m=totals.m;const month=new Date();month.setDate(1);month.setHours(0,0,0,0);const target=targets.find((x:BusinessTarget)=>x.month===monthKey())
  const progress=target?.targetProfit?Math.min(100,m.netProfit/target.targetProfit*100):0
  return <div className="space-y-5">
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Omzet hari ini" value={money(t.revenue)}/><Metric label="Profit bersih hari ini" value={money(t.netProfit)} tone={t.netProfit>=0?'good':'bad'}/><Metric label="Order selesai" value={String(t.orderCount)}/><Metric label="Rata-rata profit" value={money(t.avgProfit)}/><Metric label="Peringatan" value={String(alerts.length)} tone={alerts.length?'warn':'good'}/></section>
    <section className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><Card title="Profit 7 hari terakhir" subtitle="Profit kotor transaksi selesai per hari."><DailyBars orders={orders} days={7}/></Card><Card title="Target bulan ini" action={<button onClick={()=>setActive('Target Bisnis')} className="text-xs font-bold text-primary">Atur target</button>}><div className="space-y-3"><div className="flex justify-between text-sm"><span>Profit bersih</span><strong>{money(m.netProfit)} / {money(target?.targetProfit||0)}</strong></div><Progress value={progress}/><p className="text-xs text-muted-foreground">{target?`${pct(progress)} tercapai. Kebutuhan rata-rata sisa target dihitung di menu Target Bisnis.`:'Belum ada target bulan ini.'}</p></div></Card></section>
    <section className="grid gap-5 xl:grid-cols-2"><TopProducts orders={orders}/><Card title="Notifikasi operasional" action={<button onClick={()=>setActive('Notifikasi')} className="text-xs font-bold text-primary">Lihat semua</button>}><AlertList items={alerts.slice(0,6)}/></Card></section>
  </div>
}

function AnalyticsView({orders,expenses}:Ctx){
  const range=(days:number)=>{const s=new Date();s.setDate(s.getDate()-days+1);s.setHours(0,0,0,0);return businessTotals(orders,expenses,s,new Date())};const a7=range(7),a30=range(30)
  const startToday=new Date();startToday.setHours(0,0,0,0);const endToday=new Date();const startYesterday=new Date(startToday);startYesterday.setDate(startYesterday.getDate()-1);const endYesterday=new Date(startToday.getTime()-1);const today=businessTotals(orders,expenses,startToday,endToday);const yesterday=businessTotals(orders,expenses,startYesterday,endYesterday);const deltaProfit=yesterday.netProfit===0?(today.netProfit?100:0):(today.netProfit-yesterday.netProfit)/Math.abs(yesterday.netProfit)*100
  const games=aggregate(orders,'game');const products=aggregate(orders,'productName');const lossProducts=products.filter(x=>x.profit<0).sort((a,b)=>a.profit-b.profit)
  return <div className="space-y-5"><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><Metric label="Profit hari ini" value={money(today.netProfit)} tone={today.netProfit>=0?'good':'bad'}/><Metric label="Vs kemarin" value={`${deltaProfit>=0?'+':''}${pct(deltaProfit)}`} tone={deltaProfit>=0?'good':'bad'}/><Metric label="Profit bersih 7 hari" value={money(a7.netProfit)} tone={a7.netProfit>=0?'good':'bad'}/><Metric label="Profit bersih 30 hari" value={money(a30.netProfit)} tone={a30.netProfit>=0?'good':'bad'}/><Metric label="Order 30 hari" value={String(a30.orderCount)}/><Metric label="Pengeluaran 30 hari" value={money(a30.expenses)} tone="warn"/></section><section className="grid gap-5 xl:grid-cols-2"><Card title="30 hari" subtitle="Profit kotor per hari"><DailyBars orders={orders} days={30}/></Card><Card title="Game paling menghasilkan"><RankList rows={games.slice(0,8)}/></Card></section><div className="grid gap-5 xl:grid-cols-2"><Card title="Produk paling menghasilkan"><RankList rows={products.slice(0,12)}/></Card><Card title="Produk merugi" subtitle="Transaksi selesai dengan akumulasi profit negatif."><RankList rows={lossProducts.slice(0,12)}/></Card></div></div>
}

function TargetView({orders,expenses,targets,saveTargetsV,flash}:Ctx){
  const [month,setMonth]=useState(monthKey());const current=targets.find((x:BusinessTarget)=>x.month===month);const [profit,setProfit]=useState(current?.targetProfit||0);const [revenue,setRevenue]=useState(current?.targetRevenue||0)
  useEffect(()=>{const x=targets.find((t:BusinessTarget)=>t.month===month);setProfit(x?.targetProfit||0);setRevenue(x?.targetRevenue||0)},[month,targets])
  const start=new Date(`${month}-01T00:00:00`);const end=new Date(start);end.setMonth(end.getMonth()+1);end.setMilliseconds(-1);const total=businessTotals(orders,expenses,start,end);const progress=profit?total.netProfit/profit*100:0;const now=new Date();const lastDay=new Date(start.getFullYear(),start.getMonth()+1,0).getDate();const remaining=Math.max(1,lastDay-now.getDate());const need=Math.max(0,profit-total.netProfit)/remaining;const elapsed=Math.max(1,Math.min(lastDay,now.getDate()));const forecast=total.netProfit/elapsed*lastDay;const onTrack=profit>0&&forecast>=profit
  const save=()=>{const item={id:current?.id||id('target'),month,targetProfit:profit,targetRevenue:revenue};saveTargetsV(current?targets.map((x:BusinessTarget)=>x.month===month?item:x):[item,...targets]);appendAudit('Target bisnis',`${month} · profit ${money(profit)}`);flash('Target bisnis disimpan')}
  return <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Card title="Atur target"><div className="grid gap-3"><Field label="Bulan" type="month" value={month} onChange={setMonth}/><Num label="Target profit bersih" value={profit} onChange={setProfit}/><Num label="Target omzet" value={revenue} onChange={setRevenue}/><button onClick={save} className="btn-primary">Simpan Target</button></div></Card><Card title={`Progress ${month}`}><div className="grid gap-4"><Metric label="Profit bersih" value={money(total.netProfit)} tone={total.netProfit>=0?'good':'bad'}/><Progress value={progress}/><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Mini label="Progress" value={pct(progress)}/><Mini label="Sisa target" value={money(Math.max(0,profit-total.netProfit))}/><Mini label="Kebutuhan / hari" value={money(need)}/><Mini label="Proyeksi akhir bulan" value={money(forecast)}/><Mini label="Status proyeksi" value={profit?(onTrack?'On track':'Perlu dikejar'):'Belum ada target'}/></div></div></Card></div>
}

function AlertsView({products,orders}:Ctx){return <Card title="Notifikasi" subtitle="Stok, order terlambat, dan produk yang sedang ramai."><AlertList items={deriveAlerts(products,orders)}/></Card>}

function ProductForm({products,saveProductsV,history,saveHistoryV,ownerCloud,flash}:Ctx){
  const [form,setForm]=useState<Product>(blankProduct());const [editing,setEditing]=useState<string|null>(null)
  useEffect(()=>{const editId=localStorage.getItem('itemkuEditProduct');if(editId){const found=products.find((p:Product)=>p.id===editId);if(found){setForm(found);setEditing(found.id)}localStorage.removeItem('itemkuEditProduct')}},[products])
  const calc=useMemo(()=>calculateProduct(form),[form]);const safety=useMemo(()=>priceSafety(form,form.price,1),[form]);const set=(k:keyof Product,v:any)=>setForm(f=>({...f,[k]:typeof f[k]==='number'?Math.max(0,Number(v)||0):v}))
  const save=()=>{if(!form.name.trim())return flash('Nama produk wajib diisi');if(safety.danger&&!confirm(`Margin Guard: harga ${money(form.price)} berada di bawah BEP ${money(safety.minimumNoLoss)} dan berpotensi rugi ${money(Math.abs(safety.calc.profit))}/unit. Tetap simpan?`))return;const normalized={...form,name:form.name.trim(),game:form.game.trim()||'Lainnya',category:form.category.trim()||'Item',sku:form.sku.trim(),supplier:form.supplier.trim()};let nextH=history;if(editing&&!ownerCloud){const old=products.find((p:Product)=>p.id===editing);if(old)nextH=updateProductWithHistory(old,normalized,history)}saveProductsV(editing?products.map((p:Product)=>p.id===editing?normalized:p):[...products,normalized]);if(nextH!==history)saveHistoryV(nextH);appendAudit(editing?'Edit produk':'Tambah produk',`${normalized.game} · ${normalized.name}`);flash(editing?'Produk diperbarui':'Produk ditambahkan');setForm(blankProduct());setEditing(null)}
  return <div className="grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><Card title={editing?'Edit Produk':'Tambah Produk'} subtitle="SKU, supplier, reorder point, dan snapshot transaksi sudah didukung."><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><Field label="Game" value={form.game} onChange={v=>set('game',v)}/><Field label="Kategori" value={form.category} onChange={v=>set('category',v)}/><Field label="SKU" value={form.sku} onChange={v=>set('sku',v)}/><Field label="Nama Produk" value={form.name} onChange={v=>set('name',v)}/><Field label="Supplier" value={form.supplier} onChange={v=>set('supplier',v)}/><Num label="Stok awal" value={form.stock} onChange={v=>set('stock',v)}/><Num label="Reorder point" value={form.reorderPoint} onChange={v=>set('reorderPoint',v)}/><Num label="Modal / unit" value={form.modal} onChange={v=>set('modal',v)}/><Num label="Harga jual / unit" value={form.price} onChange={v=>set('price',v)}/><Num label="Fee Itemku (%)" value={form.fee} onChange={v=>set('fee',v)}/><Num label="Biaya tetap / order" value={form.fixed} onChange={v=>set('fixed',v)}/><Num label="Biaya lain / unit" value={form.other} onChange={v=>set('other',v)}/><Num label="Target margin (%)" value={form.target} onChange={v=>set('target',v)}/><Check label="Produk aktif" checked={form.active} onChange={v=>set('active',v)}/></div>{safety.danger?<div className="mt-4 rounded-xl border border-red-200 bg-red-50 p-3 text-xs font-semibold text-red-700 dark:bg-red-950/30 dark:text-red-200">Margin Guard: harga di bawah BEP {money(safety.minimumNoLoss)}. Potensi rugi {money(Math.abs(safety.calc.profit))}/unit.</div>:safety.belowTarget?<div className="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs font-semibold text-amber-800 dark:bg-amber-950/30 dark:text-amber-200">Harga masih profit, tetapi belum mencapai target margin. Harga target: {money(safety.targetSafe)}.</div>:<div className="mt-4 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-xs font-semibold text-emerald-800 dark:bg-emerald-950/30 dark:text-emerald-200">Margin Guard: harga berada di zona aman.</div>}<div className="mt-5 flex gap-2"><button onClick={save} className="btn-primary">{editing?'Simpan Perubahan':'Simpan Produk'}</button>{editing&&<button onClick={()=>{setForm(blankProduct());setEditing(null)}} className="btn-secondary">Batal</button>}</div></Card><Card title="Simulasi"><div className="grid gap-3"><Metric label="BEP / unit" value={money(calc.bep)} tone="warn"/><Metric label="Profit / order" value={money(calc.profit)} tone={calc.profit>=0?'good':'bad'}/><Metric label="Margin" value={pct(calc.margin)}/><Metric label="Harga target" value={money(calc.targetPrice)}/></div></Card></div>
}

function ProductList({products,orders,saveProductsV,history,saveHistoryV,setActive,flash}:Ctx){
  const [q,setQ]=useState('');const [game,setGame]=useState('Semua');const games:string[]=['Semua',...Array.from(new Set<string>(products.map((p:Product)=>String(p.game))))];const rows=products.filter((p:Product)=>(game==='Semua'||p.game===game)&&`${p.game} ${p.category} ${p.name} ${p.sku} ${p.supplier}`.toLowerCase().includes(q.toLowerCase()))
  const edit=(p:Product)=>{localStorage.setItem('itemkuEditProduct',p.id);setActive('Tambah Produk')};const remove=(p:Product)=>{const used=orders.some((o:Order)=>o.productId===p.id);if(used){if(!confirm(`Produk ${p.name} punya histori transaksi. Arsipkan/nonaktifkan?`))return;saveProductsV(products.map((x:Product)=>x.id===p.id?{...x,active:false}:x));appendAudit('Arsip produk',`${p.game} · ${p.name}`);flash('Produk diarsipkan')}else{if(!confirm(`Hapus ${p.name}?`))return;saveProductsV(products.filter((x:Product)=>x.id!==p.id));appendAudit('Hapus produk',`${p.game} · ${p.name}`);flash('Produk dihapus')}}
  const toggle=(p:Product)=>saveProductsV(products.map((x:Product)=>x.id===p.id?{...x,active:!x.active}:x))
  return <Card title="Daftar Produk" subtitle={`${products.length} produk · pencarian, filter, dan indikator restock.`} action={<div className="flex gap-2"><select value={game} onChange={e=>setGame(e.target.value)} className="input h-9"><option>Semua</option>{games.slice(1).map(g=><option key={g}>{g}</option>)}</select><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Cari produk/SKU" className="input h-9 w-48"/></div>}><Table headers={['Produk','SKU','Supplier','Stok','Modal','Harga','Profit','Status','Aksi']}>{rows.map((p:Product)=>{const c=calculateProduct(p);return <tr key={p.id}><Td><strong>{p.name}</strong><small className="block text-muted-foreground">{p.game} · {p.category}</small></Td><Td>{p.sku||'-'}</Td><Td>{p.supplier||'-'}</Td><Td><span className={p.stock===0?'font-bold text-red-600':p.stock<=p.reorderPoint?'font-bold text-amber-600':'font-bold text-emerald-700'}>{p.stock}</span><small className="block text-muted-foreground">min {p.reorderPoint}</small></Td><Td>{money(p.modal)}</Td><Td>{money(p.discountEnabled&&p.discountPrice?p.discountPrice:p.price)}</Td><Td className={c.profit>=0?'text-emerald-700':'text-red-600'}>{money(c.profit)}</Td><Td><button onClick={()=>toggle(p)}><Badge tone={p.active?'green':'gray'}>{p.active?'Aktif':'Nonaktif'}</Badge></button></Td><Td><div className="flex gap-1"><button onClick={()=>{localStorage.setItem('itemkuRestockProduct',p.id);setActive('Restock')}} className="tiny-btn">+ Stok</button><button onClick={()=>edit(p)} className="tiny-btn">Edit</button><button onClick={()=>remove(p)} className="tiny-btn text-red-600">Hapus</button></div></Td></tr>})}</Table></Card>
}

function RestockView({products,restocks,saveProductsV,saveRestocksV,ownerCloud,hydrateCloud,history,saveHistoryV,flash}:Ctx){
  const [productId,setProductId]=useState('');const [qty,setQty]=useState(1);const [unitCost,setUnitCost]=useState(0);const [supplier,setSupplier]=useState('');const [note,setNote]=useState('');
  useEffect(()=>{const x=localStorage.getItem('itemkuRestockProduct');if(x){setProductId(x);const p=products.find((a:Product)=>a.id===x);if(p){setUnitCost(p.modal);setSupplier(p.supplier)}localStorage.removeItem('itemkuRestockProduct')}},[products])
  const p=products.find((x:Product)=>x.id===productId)
  const submit=async()=>{if(!p)return flash('Pilih produk');if(qty<=0)return flash('Qty tidak valid');try{if(ownerCloud){await cloudAction('restock',{productId,qty,unitCost,supplier,note});await hydrateCloud()}else{const previous=p.stock,newStock=p.stock+qty;const newModal=newStock?((p.stock*p.modal)+(qty*unitCost))/newStock:unitCost;const updated={...p,stock:newStock,modal:newModal,supplier:supplier||p.supplier,stockSince:p.stock===0?new Date().toISOString():p.stockSince};saveProductsV(products.map((x:Product)=>x.id===p.id?updated:x));saveHistoryV(updateProductWithHistory(p,updated,history));const r:Restock={id:id('restock'),productId:p.id,productName:p.name,supplier:supplier||p.supplier,qty,unitCost,totalCost:qty*unitCost,previousStock:previous,newStock,createdAt:new Date().toISOString(),note};saveRestocksV([r,...restocks]);appendAudit('Restock',`${p.name} +${qty} unit · ${money(unitCost)}`)}flash('Restock berhasil');setQty(1);setNote('')}catch(e:any){flash(e.message||'Restock gagal')}}
  return <div className="space-y-5"><div className="grid gap-5 xl:grid-cols-[.7fr_1.3fr]"><Card title="Restock Produk" subtitle="Modal baru dihitung weighted average; cloud memakai transaksi atomic."><div className="grid gap-3"><Select label="Produk" value={productId} onChange={v=>{setProductId(v);const x=products.find((a:Product)=>a.id===v);if(x){setUnitCost(x.modal);setSupplier(x.supplier)}}} options={[['','Pilih produk'],...products.map((x:Product)=>[x.id,`${x.game} · ${x.name} (${x.stock})`])]}/><Num label="Qty masuk" value={qty} onChange={setQty}/><Num label="Harga modal pembelian / unit" value={unitCost} onChange={setUnitCost}/><Field label="Supplier" value={supplier} onChange={setSupplier}/><Field label="Catatan" value={note} onChange={setNote}/>{p&&<div className="rounded-xl bg-muted p-3 text-xs">Stok {p.stock} → <strong>{p.stock+qty}</strong> · total pembelian <strong>{money(qty*unitCost)}</strong></div>}<button onClick={submit} className="btn-primary">+ Simpan Restock</button></div></Card><Card title="Riwayat Restock"><Table headers={['Tanggal','Produk','Supplier','Qty','Modal/unit','Total','Stok']}>{restocks.slice(0,30).map((r:Restock)=><tr key={r.id}><Td>{fmt(r.createdAt)}</Td><Td>{r.productName}</Td><Td>{r.supplier||'-'}</Td><Td>+{r.qty}</Td><Td>{money(r.unitCost)}</Td><Td>{money(r.totalCost)}</Td><Td>{r.previousStock} → {r.newStock}</Td></tr>)}</Table></Card></div></div>
}

function AgingView({products,saveProductsV,flash}:Ctx){const rows=products.filter((p:Product)=>p.stock>0&&Date.now()-new Date(p.stockSince).getTime()>=7*86400000);const toggle=(p:Product)=>{const bep=calculateProduct(p).bep;const suggested=Math.max(Math.ceil(bep*1.03),Math.round(p.price*.9));saveProductsV(products.map((x:Product)=>x.id===p.id?{...x,discountEnabled:!x.discountEnabled,discountPrice:x.discountEnabled?0:suggested}:x));appendAudit('Diskon stok aging',`${p.name} · ${p.discountEnabled?'off':money(suggested)}`);flash('Diskon diperbarui')};return <Card title="Stok Menumpuk" subtitle="Stok tersimpan minimal 7 hari.">{rows.length?<div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{rows.map((p:Product)=><div key={p.id} className="rounded-xl border p-4"><div className="flex justify-between"><div><strong>{p.name}</strong><p className="text-xs text-muted-foreground">{p.game} · {p.stock} unit</p></div><Badge tone="amber">{Math.floor((Date.now()-new Date(p.stockSince).getTime())/86400000)} hari</Badge></div><p className="mt-3 text-xs">BEP {money(calculateProduct(p).bep)}</p><button onClick={()=>toggle(p)} className="btn-secondary mt-3 w-full">{p.discountEnabled?'Matikan diskon':'Aktifkan saran diskon'}</button></div>)}</div>:<Empty text="Belum ada stok menumpuk."/>}</Card>}

function PriceHistoryView({history}:Ctx){return <Card title="Riwayat Harga & Modal" subtitle="Perubahan harga dan modal disimpan untuk melihat tren margin."><Table headers={['Tanggal','Produk','Jenis','Sebelum','Sesudah','Perubahan']}>{history.map((h:PriceHistory)=><tr key={h.id}><Td>{fmt(h.createdAt)}</Td><Td>{h.productName}</Td><Td><Badge tone={h.field==='price'?'blue':'amber'}>{h.field==='price'?'Harga jual':'Modal'}</Badge></Td><Td>{money(h.fromValue)}</Td><Td>{money(h.toValue)}</Td><Td className={h.toValue>h.fromValue?'text-amber-700':'text-emerald-700'}>{h.toValue>h.fromValue?'+':''}{money(h.toValue-h.fromValue)}</Td></tr>)}</Table>{!history.length&&<Empty text="Belum ada perubahan harga."/>}</Card>}

function OrderCenter({products,orders,saveProductsV,saveOrdersV,ownerCloud,hydrateCloud,settings,channelRules,flash}:Ctx){
  const [productId,setProductId]=useState('');const [buyer,setBuyer]=useState('');const [serverId,setServerId]=useState('');const [channel,setChannel]=useState(settings.defaultChannel||'Itemku');const [qty,setQty]=useState(1);const [note,setNote]=useState('');const [q,setQ]=useState('');const [status,setStatus]=useState('Aktif');const [game,setGame]=useState('Semua');const [workerFilter,setWorkerFilter]=useState('Semua');const [sort,setSort]=useState('Terbaru')
  const [cloudRows,setCloudRows]=useState<Order[]>([]);const [cloudLoaded,setCloudLoaded]=useState(false);const [hasMore,setHasMore]=useState(false);const [loadingPage,setLoadingPage]=useState(false)
  const loadPage=async(reset=true)=>{if(!ownerCloud)return;setLoadingPage(true);try{const base=reset?0:cloudRows.length;const d=await pullCloudOrders({limit:50,offset:base,search:q,status:status==='Aktif'||status==='Semua'?'':status,game:game==='Semua'?'':game});setCloudRows(reset?d.orders:[...cloudRows,...d.orders]);setHasMore(d.hasMore);setCloudLoaded(true)}catch(e:any){flash(e.message||'Gagal mengambil halaman order')}finally{setLoadingPage(false)}}
  useEffect(()=>{if(!ownerCloud){setCloudLoaded(false);return};const t=setTimeout(()=>void loadPage(true),250);return()=>clearTimeout(t)},[ownerCloud,q,status,game])
  const create=async()=>{const p=products.find((x:Product)=>x.id===productId);if(!p)return flash('Pilih produk');if(!buyer.trim())return flash('Username/User ID wajib diisi');if(qty<1)return flash('Qty tidak valid');try{if(ownerCloud){await cloudAction('createOrder',{productId,buyerIdentifier:buyer.trim(),serverId:serverId.trim(),channel,qty,note:note.trim()});await hydrateCloud();await loadPage(true)}else{if(p.stock<qty)return flash(`Stok tidak cukup. Tersedia ${p.stock}`);const rule=feeForChannel(channelRules||[],channel,p);const priced={...p,fee:rule.feePercent,fixed:rule.fixedFee};const o:Order={id:id('order'),invoiceNo:nextLocalInvoice(orders),productId:p.id,productName:p.name,game:p.game,supplierSnapshot:p.supplier,buyerIdentifier:buyer.trim(),serverId:serverId.trim(),channel:channel||'Itemku',qty,note:note.trim(),createdAt:new Date().toISOString(),status:'Baru',snapshot:makeSnapshot(priced,qty)};saveProductsV(products.map((x:Product)=>x.id===p.id?{...x,stock:x.stock-qty}:x));saveOrdersV([...orders,o]);appendAudit('Order dibuat',`${o.invoiceNo} · ${p.name}`)}setBuyer('');setServerId('');setNote('');setQty(1);flash('Order berhasil dibuat')}catch(e:any){flash(e.message||'Order gagal')}}
  const transition=async(o:Order,next:OrderStatus)=>{let reason='',restore=false;if(next==='Refund'||next==='Cancel'){reason=prompt('Alasan:')?.trim()||'';if(!reason)return;restore=confirm('Kembalikan stok ke persediaan?')}try{if(ownerCloud){await cloudAction('transitionOrder',{orderId:o.id,status:next,refundReason:reason,restoreStock:restore});await hydrateCloud();await loadPage(true)}else{let ps=products;if(restore&&!o.stockRestored&&o.productId)ps=products.map((p:Product)=>p.id===o.productId?{...p,stock:p.stock+o.qty}:p);const now=new Date().toISOString();const updated={...o,status:next,processingAt:next==='Diproses'?(o.processingAt||now):o.processingAt,completedAt:['Selesai','Refund','Cancel'].includes(next)?now:o.completedAt,refundReason:reason||o.refundReason,stockRestored:o.stockRestored||restore};saveProductsV(ps);saveOrdersV(orders.map((x:Order)=>x.id===o.id?updated:x));appendAudit(`Order → ${next}`,`${o.invoiceNo} · ${o.productName}`)}flash(`Order ${next}`)}catch(e:any){flash(e.message||'Update order gagal')}}
  const base=ownerCloud&&cloudLoaded?cloudRows:orders;const games:string[]=['Semua',...Array.from(new Set<string>(orders.map((o:Order)=>String(o.game))))];const workerNames:string[]=['Semua','Belum diambil',...Array.from(new Set<string>(orders.map((o:Order)=>o.assignedWorker).filter((name: string | undefined): name is string=>Boolean(name))))];let rows=base.filter((o:Order)=>{const s=status==='Semua'||(status==='Aktif'?(o.status==='Baru'||o.status==='Diproses'||o.status==='Menunggu'):o.status===status);const w=workerFilter==='Semua'||(workerFilter==='Belum diambil'?!o.assignedWorker:o.assignedWorker===workerFilter);return s&&w&&(game==='Semua'||o.game===game)&&`${o.invoiceNo} ${o.buyerIdentifier} ${o.productName} ${o.assignedWorker||''}`.toLowerCase().includes(q.toLowerCase())});rows=rows.sort((a:Order,b:Order)=>(sort==='Terbaru'?-1:1)*(new Date(a.createdAt).getTime()-new Date(b.createdAt).getTime()))
  const channelOptions=(channelRules?.filter((x:ChannelRule)=>x.active)||[]).map((x:ChannelRule)=>[x.name,x.name]);
  return <div className="space-y-5"><Card title="Buat Order" subtitle="Cloud memakai transaksi atomic, fee otomatis per channel, snapshot finansial, invoice, dan ledger stok."><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><Select label="Produk" value={productId} onChange={setProductId} options={[['','Pilih produk'],...products.filter((p:Product)=>p.active).map((p:Product)=>[p.id,`${p.game} · ${p.name} (${p.stock})`])]}/><Field label="Username / User ID" value={buyer} onChange={setBuyer}/><Field label="Server / UID tambahan" value={serverId} onChange={setServerId}/><Select label="Channel" value={channel} onChange={setChannel} options={channelOptions.length?channelOptions:[[channel,channel]]}/><Num label="Qty" value={qty} onChange={setQty}/><Field label="Catatan" value={note} onChange={setNote}/></div><button onClick={create} className="btn-primary mt-4">+ Buat Order</button></Card><Card title="Order Center" subtitle={`${rows.length} order ditampilkan${ownerCloud?' · server-side pagination 50/order':''}`} action={<div className="flex flex-wrap gap-2"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Cari invoice/pembeli..." className="input h-9 w-48"/><select className="input h-9" value={status} onChange={e=>setStatus(e.target.value)}>{['Aktif','Semua','Baru','Diproses','Menunggu','Selesai','Refund','Cancel'].map(x=><option key={x}>{x}</option>)}</select><select className="input h-9" value={game} onChange={e=>setGame(e.target.value)}>{games.map(g=><option key={g}>{g}</option>)}</select><select className="input h-9" value={workerFilter} onChange={e=>setWorkerFilter(e.target.value)}>{workerNames.map(w=><option key={w}>{w}</option>)}</select><select className="input h-9" value={sort} onChange={e=>setSort(e.target.value)}><option>Terbaru</option><option>Terlama</option></select></div>}><Table headers={['Invoice','Pembeli','Produk','Nilai','Status','Worker','Waktu','Aksi']}>{rows.map((o:Order)=><tr key={o.id}><Td><strong>{o.invoiceNo}</strong><small className="block text-muted-foreground">{o.channel}</small></Td><Td><div className="flex items-center gap-2"><span>{o.buyerIdentifier}</span><button onClick={()=>navigator.clipboard?.writeText(o.buyerIdentifier)} className="tiny-btn">Copy</button></div>{o.serverId&&<small className="block text-muted-foreground">{o.serverId}</small>}</Td><Td><strong>{o.productName} × {o.qty}</strong><small className="block text-muted-foreground">{o.game}</small></Td><Td>{money(o.snapshot.revenue)}<small className="block text-emerald-700">+{money(o.snapshot.profit)}</small></Td><Td><Status status={o.status}/></Td><Td>{o.assignedWorker||'-'}</Td><Td>{fmt(o.createdAt)}</Td><Td><div className="flex flex-wrap gap-1">{(o.status==='Baru'||o.status==='Menunggu')&&<button onClick={()=>transition(o,'Diproses')} className="tiny-btn">Proses</button>}{o.status==='Diproses'&&<button onClick={()=>transition(o,'Menunggu')} className="tiny-btn text-amber-700">Menunggu</button>}{(o.status==='Baru'||o.status==='Diproses'||o.status==='Menunggu')&&<button onClick={()=>transition(o,'Selesai')} className="tiny-btn text-emerald-700">Selesai</button>}{(o.status==='Baru'||o.status==='Diproses'||o.status==='Menunggu')&&<button onClick={()=>transition(o,'Refund')} className="tiny-btn text-red-600">Refund</button>}</div></Td></tr>)}</Table>{ownerCloud&&hasMore&&<div className="mt-4 text-center"><button disabled={loadingPage} onClick={()=>void loadPage(false)} className="btn-secondary">{loadingPage?'Memuat...':'Load 50 order berikutnya'}</button></div>}</Card></div>
}

function CustomerView({orders,customerNotes,saveCustomerNotesV,flash}:Ctx){
  const [q,setQ]=useState('');const [editing,setEditing]=useState<string|null>(null);const [note,setNote]=useState('')
  const rows=customerStats(orders).filter(x=>x.buyer.toLowerCase().includes(q.toLowerCase()))
  const noteFor=(buyer:string)=>customerNotes.find((n:CustomerNote)=>n.buyerIdentifier.trim().toLowerCase()===buyer.trim().toLowerCase())
  const edit=(buyer:string)=>{const existing=noteFor(buyer);setEditing(buyer);setNote(existing?.note||'')}
  const save=()=>{if(!editing)return;const existing=noteFor(editing);const now=new Date().toISOString();const item:CustomerNote={id:existing?.id||id('customer'),buyerIdentifier:editing,note:note.trim(),createdAt:existing?.createdAt||now,updatedAt:now};const next=existing?customerNotes.map((x:CustomerNote)=>x.id===existing.id?item:x):[item,...customerNotes];saveCustomerNotesV(next);appendAudit('Catatan pelanggan',editing);setEditing(null);setNote('');flash('Catatan pelanggan disimpan')}
  return <div className="space-y-5"><Card title="Histori Pelanggan" subtitle="Berdasarkan Username/User ID transaksi; catatan internal Owner tersimpan terpisah." action={<input value={q} onChange={e=>setQ(e.target.value)} className="input h-9" placeholder="Cari pelanggan"/>}><Table headers={['Pembeli','Order sukses','Total belanja','Profit','Refund','Produk terakhir','Terakhir order','Catatan']}>{rows.map(x=>{const n=noteFor(x.buyer);return <tr key={x.buyer}><Td><strong>{x.buyer}</strong></Td><Td>{x.orders}</Td><Td>{money(x.spend)}</Td><Td className="text-emerald-700">{money(x.profit)}</Td><Td>{x.refunds}</Td><Td>{x.lastProduct}</Td><Td>{fmt(x.lastAt)}</Td><Td><div className="max-w-64"><p className="line-clamp-2 text-xs text-muted-foreground">{n?.note||'Belum ada catatan'}</p><button onClick={()=>edit(x.buyer)} className="tiny-btn mt-1">{n?'Edit catatan':'+ Catatan'}</button></div></Td></tr>})}</Table>{!rows.length&&<Empty text="Belum ada histori pelanggan."/>}</Card>{editing&&<Card title={`Catatan · ${editing}`}><div className="grid gap-3"><textarea value={note} onChange={e=>setNote(e.target.value)} rows={4} className="input min-h-28 py-3" placeholder="Contoh: pelanggan repeat order, prefer proses cepat, pernah kendala tertentu..."/><div className="flex gap-2"><button onClick={save} className="btn-primary">Simpan Catatan</button><button onClick={()=>{setEditing(null);setNote('')}} className="btn-secondary">Batal</button></div></div></Card>}</div>
}

function CashFlowView({orders,expenses,restocks,saveExpensesV,flash}:Ctx){const [category,setCategory]=useState('Iklan');const [amount,setAmount]=useState(0);const [date,setDate]=useState(new Date().toISOString().slice(0,16));const [note,setNote]=useState('');const total=businessTotals(orders,expenses);const inventoryOut=restocks.reduce((sum:number,r:Restock)=>sum+r.totalCost,0);const cashIn=orders.filter((o:Order)=>o.status==='Selesai').reduce((sum:number,o:Order)=>sum+o.snapshot.revenue,0);const cashNet=cashIn-inventoryOut-total.expenses;const add=()=>{if(amount<=0)return flash('Nominal pengeluaran harus > 0');const e:Expense={id:id('expense'),category,amount,date:new Date(date).toISOString(),note};saveExpensesV([e,...expenses]);appendAudit('Tambah pengeluaran',`${category} · ${money(amount)}`);setAmount(0);setNote('');flash('Pengeluaran ditambahkan')};const remove=(x:Expense)=>{if(!confirm('Hapus pengeluaran ini?'))return;saveExpensesV(expenses.filter((e:Expense)=>e.id!==x.id));flash('Pengeluaran dihapus')};return <div className="space-y-5"><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><Metric label="Kas masuk penjualan" value={money(cashIn)}/><Metric label="Pembelian stok" value={money(inventoryOut)} tone="warn"/><Metric label="Arus kas bersih" value={money(cashNet)} tone={cashNet>=0?'good':'bad'}/><Metric label="Profit kotor" value={money(total.grossProfit)} tone="good"/><Metric label="Pengeluaran" value={money(total.expenses)} tone="warn"/><Metric label="Profit bersih" value={money(total.netProfit)} tone={total.netProfit>=0?'good':'bad'}/></section><div className="grid gap-5 xl:grid-cols-[.6fr_1.4fr]"><Card title="Catat Pengeluaran"><div className="grid gap-3"><Select label="Kategori" value={category} onChange={setCategory} options={['Iklan','Admin','Tools','Internet','Fee Transfer','Bonus Worker','Lainnya'].map(x=>[x,x])}/><Num label="Nominal" value={amount} onChange={setAmount}/><Field label="Tanggal" type="datetime-local" value={date} onChange={setDate}/><Field label="Catatan" value={note} onChange={setNote}/><button onClick={add} className="btn-primary">+ Simpan Pengeluaran</button></div></Card><Card title="Riwayat Pengeluaran"><Table headers={['Tanggal','Kategori','Nominal','Catatan','']}>{expenses.map((e:Expense)=><tr key={e.id}><Td>{fmt(e.date)}</Td><Td>{e.category}</Td><Td className="text-red-600">-{money(e.amount)}</Td><Td>{e.note||'-'}</Td><Td><button onClick={()=>remove(e)} className="tiny-btn text-red-600">Hapus</button></Td></tr>)}</Table></Card></div></div>}

function ProfitByGame({orders}:Ctx){return <Card title="Profit per Game" subtitle="Menentukan game yang layak diperbesar stoknya."><RankList rows={aggregate(orders,'game')}/></Card>}
function ProfitSupplier({orders,products}:Ctx){const supplierById=new Map<string,string>((products as Product[]).map((p:Product)=>[p.id,p.supplier||'Tanpa Supplier']));const map=new Map<string,{label:string,revenue:number,profit:number,orders:number}>();orders.filter((o:Order)=>o.status==='Selesai').forEach((o:Order)=>{const label=o.supplierSnapshot||supplierById.get(o.productId)||'Tidak diketahui';const x=map.get(label)||{label,revenue:0,profit:0,orders:0};x.revenue+=o.snapshot.revenue;x.profit+=o.snapshot.profit;x.orders++;map.set(label,x)});return <Card title="Profit per Supplier" subtitle="Bandingkan kontribusi margin berdasarkan supplier produk."><RankList rows={[...map.values()].sort((a,b)=>b.profit-a.profit)}/></Card>}

function OpportunityView({opportunities,saveOppsV,flash}:Ctx){
  const [form,setForm]=useState<Opportunity>({id:id('opp'),game:'Roblox',product:'',category:'Item',marketPrice:0,previousMarketPrice:0,capital:0,soldSignal:0,previousSoldSignal:0,listingSignal:0,competitorCount:0,checkedAt:new Date().toISOString(),note:'',trend:'baru'});const [editing,setEditing]=useState<string|null>(null)
  const set=(k:keyof Opportunity,v:any)=>setForm(f=>({...f,[k]:typeof f[k]==='number'?Math.max(0,Number(v)||0):v}))
  const save=()=>{if(!form.game.trim()||!form.product.trim())return flash('Game dan produk wajib diisi');const old=opportunities.find((x:Opportunity)=>x.id===editing);const nextItem={...form,id:editing||form.id,previousMarketPrice:old?.marketPrice||form.previousMarketPrice,previousSoldSignal:old?.soldSignal||form.previousSoldSignal,trend:old?inferOpportunityTrend(form,old):'baru',checkedAt:new Date().toISOString()};saveOppsV(editing?opportunities.map((x:Opportunity)=>x.id===editing?nextItem:x):[nextItem,...opportunities]);appendAudit(editing?'Update riset Itemku':'Tambah riset Itemku',`${nextItem.game} · ${nextItem.product}`);setEditing(null);setForm({...nextItem,id:id('opp'),product:'',marketPrice:0,capital:0,soldSignal:0,listingSignal:0,competitorCount:0,note:'',trend:'baru'});flash('Riset disimpan')}
  const edit=(x:Opportunity)=>{setEditing(x.id);setForm(x)};const remove=(x:Opportunity)=>{saveOppsV(opportunities.filter((o:Opportunity)=>o.id!==x.id));flash('Riset dihapus')}
  const rows=[...opportunities].sort((a,b)=>opportunityScore(b)-opportunityScore(a))
  return <div className="space-y-5"><Card title="Riset Itemku V2" subtitle="Watchlist peluang: harga pasar, demand, kompetitor, trend, dan skor otomatis."><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Field label="Game" value={form.game} onChange={v=>set('game',v)}/><Field label="Produk" value={form.product} onChange={v=>set('product',v)}/><Field label="Kategori" value={form.category} onChange={v=>set('category',v)}/><Num label="Harga pasar" value={form.marketPrice} onChange={v=>set('marketPrice',v)}/><Num label="Modal kamu" value={form.capital} onChange={v=>set('capital',v)}/><Num label="Sinyal terjual" value={form.soldSignal} onChange={v=>set('soldSignal',v)}/><Num label="Jumlah listing" value={form.listingSignal} onChange={v=>set('listingSignal',v)}/><Num label="Kompetitor" value={form.competitorCount} onChange={v=>set('competitorCount',v)}/><Field label="Catatan" value={form.note} onChange={v=>set('note',v)}/><div className="flex items-end"><button onClick={save} className="btn-primary w-full">{editing?'Update Watchlist':'+ Tambah Watchlist'}</button></div></div></Card><Card title="Watchlist Peluang"><Table headers={['Game / Produk','Harga pasar','Modal','Potensi kotor','Terjual','Listing / Seller','Trend','Skor','Status','Aksi']}>{rows.map((x:Opportunity)=>{const score=opportunityScore(x);return <tr key={x.id}><Td><strong>{x.product}</strong><small className="block text-muted-foreground">{x.game} · {x.category}</small></Td><Td>{money(x.marketPrice)}</Td><Td>{money(x.capital)}</Td><Td className="text-emerald-700">{money(Math.max(0,x.marketPrice-x.capital))}</Td><Td>{x.soldSignal.toLocaleString('id-ID')}</Td><Td>{x.listingSignal.toLocaleString('id-ID')} / {x.competitorCount}</Td><Td><TrendBadge trend={x.trend}/></Td><Td><strong>{score}/100</strong></Td><Td>{opportunityLabel(score)}</Td><Td><div className="flex gap-1"><button onClick={()=>edit(x)} className="tiny-btn">Update</button><button onClick={()=>remove(x)} className="tiny-btn text-red-600">Hapus</button></div></Td></tr>})}</Table></Card></div>
}

function WorkerView({workers,saveWorkersV,products,cloudUser,flash}:Ctx){
  const games:string[]=[...new Set<string>((products as Product[]).map((p:Product)=>p.game))]
  const persist=(next:Worker[])=>{saveWorkersV(next)}
  const add=()=>{const w:Worker={id:id('worker'),cloudUserId:'',name:`Worker ${workers.length+1}`,username:'',password:'',active:false,enabled:true,permissions:{canProcessOrders:true,canRefund:false,canViewStock:true,canViewFinancials:false,allowedGames:[]}};persist([...workers,w])}
  const update=(i:number,patch:any)=>persist(workers.map((w:Worker,n:number)=>n===i?{...w,...patch}:w))
  const syncProfile=async(w:Worker)=>{if(!cloudUser||cloudUser.role!=='owner')return flash('Login Cloud Owner dulu');if(!w.cloudUserId?.trim())return flash('Isi UUID Supabase Auth worker dulu');try{await syncEntity('profiles',[{id:w.cloudUserId.trim(),name:w.name,role:'worker',active:w.enabled!==false,permissions:{canProcessOrders:w.permissions.canProcessOrders,canRefund:w.permissions.canRefund,canViewStock:w.permissions.canViewStock,canViewFinancials:w.permissions.canViewFinancials},allowedGames:w.permissions.allowedGames}],false);flash('Permission worker dikirim ke cloud')}catch(e:any){flash(e.message||'Sync worker gagal')}}
  return <div className="space-y-5"><Card title="Worker & Permission" subtitle="Cloud worker memakai Supabase Auth; password lokal hanya fallback offline." action={<button onClick={add} className="btn-primary">+ Worker lokal</button>}><div className="grid gap-4 xl:grid-cols-2">{workers.map((w:Worker,i:number)=><div key={w.id} className="rounded-xl border p-4"><div className="flex items-start justify-between gap-3"><div className="flex-1"><Field label="Nama" value={w.name} onChange={v=>update(i,{name:v})}/><p className="mt-1 text-[10px] text-muted-foreground">Cloud profile ID harus sama dengan UUID Supabase Auth jika ingin tombol sync.</p></div><button onClick={()=>update(i,{enabled:w.enabled===false})}><Badge tone={w.enabled!==false?'green':'gray'}>{w.enabled!==false?'Aktif':'Nonaktif'}</Badge></button></div><div className="mt-3 grid gap-3 sm:grid-cols-2"><Field label="UUID Supabase Auth" value={w.cloudUserId||''} onChange={v=>update(i,{cloudUserId:v})}/><Field label="Username fallback" value={w.username} onChange={v=>update(i,{username:v})}/><Field label="Password fallback" type="password" value={w.password} onChange={v=>update(i,{password:v})}/></div><div className="mt-4 grid gap-2 sm:grid-cols-2 xl:grid-cols-4"><Check label="Boleh proses order" checked={w.permissions.canProcessOrders} onChange={v=>update(i,{permissions:{...w.permissions,canProcessOrders:v}})}/><Check label="Boleh refund" checked={w.permissions.canRefund} onChange={v=>update(i,{permissions:{...w.permissions,canRefund:v}})}/><Check label="Lihat stok" checked={w.permissions.canViewStock} onChange={v=>update(i,{permissions:{...w.permissions,canViewStock:v}})}/><Check label="Lihat finansial" checked={w.permissions.canViewFinancials} onChange={v=>update(i,{permissions:{...w.permissions,canViewFinancials:v}})}/></div><div className="mt-4"><p className="mb-2 text-xs font-bold">Game yang boleh ditangani <span className="font-normal text-muted-foreground">(kosong = semua)</span></p><div className="flex flex-wrap gap-2">{games.map(g=><button key={g} onClick={()=>{const has=w.permissions.allowedGames.includes(g);update(i,{permissions:{...w.permissions,allowedGames:has?w.permissions.allowedGames.filter(x=>x!==g):[...w.permissions.allowedGames,g]}})}}><Badge tone={w.permissions.allowedGames.includes(g)?'blue':'gray'}>{g}</Badge></button>)}</div></div><div className="mt-4 flex gap-2"><button onClick={()=>syncProfile(w)} className="btn-secondary">Sync Permission Cloud</button><button onClick={()=>{if(confirm(`Hapus ${w.name}?`))persist(workers.filter((_:Worker,n:number)=>n!==i))}} className="btn-secondary text-red-600">Hapus</button></div></div>)}</div></Card><Card title="Setup akun cloud"><p className="text-sm text-muted-foreground">Buat akun Worker di Supabase Authentication, lalu salin UUID user tersebut ke field <strong>UUID Supabase Auth</strong> jika ingin permission tersambung penuh. Schema V3 mengunci refund, game, dan akses finansial di server.</p></Card></div>
}

function WorkerStatsView({orders}:Ctx){const rows=workerStats(orders);return <Card title="Statistik Worker" subtitle="Jumlah selesai, refund, order aktif, dan rata-rata waktu proses."><Table headers={['Worker','Selesai','Refund','Sedang diproses','Rata-rata proses','Aktivitas terakhir']}>{rows.map(x=><tr key={x.worker}><Td><strong>{x.worker}</strong></Td><Td>{x.completed}</Td><Td>{x.refunds}</Td><Td>{x.active}</Td><Td>{x.avgMinutes?`${x.avgMinutes.toFixed(1)} menit`:'-'}</Td><Td>{fmt(x.lastAt)}</Td></tr>)}</Table>{!rows.length&&<Empty text="Belum ada aktivitas worker."/>}</Card>}

function ReportView({orders,expenses}:Ctx){const [period,setPeriod]=useState('30');const days=Number(period);const start=new Date();start.setDate(start.getDate()-days+1);start.setHours(0,0,0,0);const total=businessTotals(orders,expenses,start,new Date());return <div className="space-y-5"><Card title="Laporan" action={<select className="input h-9" value={period} onChange={e=>setPeriod(e.target.value)}><option value="1">Hari ini</option><option value="7">7 hari</option><option value="30">30 hari</option><option value="90">90 hari</option></select>}><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Order" value={String(total.orderCount)}/><Metric label="Omzet" value={money(total.revenue)}/><Metric label="Profit kotor" value={money(total.grossProfit)} tone="good"/><Metric label="Pengeluaran" value={money(total.expenses)} tone="warn"/><Metric label="Profit bersih" value={money(total.netProfit)} tone={total.netProfit>=0?'good':'bad'}/></section></Card><Card title="Grafik"><DailyBars orders={orders} days={days}/></Card></div>}

function BackupView({products,orders,restocks,customerNotes,expenses,targets,opportunities,history,hydrateCloud,ownerCloud,flash}:Ctx){
  const download=(name:string,text:string,type='application/json')=>{const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
  const backup=()=>{const now=new Date().toISOString();const base=JSON.parse(exportBackup()),v4=JSON.parse(exportV4Backup());const v52=JSON.parse(exportV52Backup());download(`itemku-v5.2-backup-${now.replace(/[:.]/g,'-')}.json`,JSON.stringify({...base,version:5.2,release:'5.2.0-automation',exportedAt:now,v4,v52},null,2));localStorage.setItem('itemkuLastBackupAt',now);window.dispatchEvent(new Event('itemku:backup'));appendAudit('Backup V5.2 dibuat',now);flash('Backup V5.2 berhasil dibuat')}
  const csv=()=>{const esc=(v:any)=>`"${String(v??'').replace(/"/g,'""')}"`;const lines=[['Invoice','Tanggal','Game','Produk','Pembeli','Qty','Status','Omzet','Modal+Biaya','Profit','Worker'].map(esc).join(',')];orders.forEach((o:Order)=>lines.push([o.invoiceNo,o.createdAt,o.game,o.productName,o.buyerIdentifier,o.qty,o.status,o.snapshot.revenue,o.snapshot.totalCost,o.snapshot.profit,o.assignedWorker||''].map(esc).join(',')));download(`itemku-transaksi-${new Date().toISOString().slice(0,10)}.csv`,lines.join('\n'),'text/csv;charset=utf-8')}
  const restore=async(file:File)=>{try{const raw=await file.text();const parsed=JSON.parse(raw);restoreBackup(raw);if(parsed?.v4)restoreV4Backup(JSON.stringify(parsed.v4));if(parsed?.v52)restoreV52Backup(JSON.stringify(parsed.v52));appendAudit('Restore backup',file.name);location.reload()}catch(e:any){flash(e.message||'Restore gagal')}}
  return <div className="space-y-5"><section className="grid gap-3 md:grid-cols-3"><button onClick={backup} className="action-card"><strong>Backup JSON V5.2 lengkap</strong><span>Termasuk data bisnis, V4, approval V5.2, automation run, jadwal laporan, dan histori scheduled report.</span></button><button onClick={csv} className="action-card"><strong>Export transaksi CSV</strong><span>Bisa dibuka di Excel / Google Sheets.</span></button><label className="action-card cursor-pointer"><strong>Restore Backup</strong><span>Mendukung backup legacy hingga V5.2.</span><input type="file" accept=".json,application/json" className="hidden" onChange={e=>{const f=e.target.files?.[0];if(f)void restore(f)}}/></label></section><Card title="Ringkasan backup"><div className="grid gap-3 sm:grid-cols-4 xl:grid-cols-8"><Mini label="Produk" value={String(products.length)}/><Mini label="Order" value={String(orders.length)}/><Mini label="Restock" value={String(restocks.length)}/><Mini label="Catatan pelanggan" value={String(customerNotes.length)}/><Mini label="Expense" value={String(expenses.length)}/><Mini label="Target" value={String(targets.length)}/><Mini label="Riset" value={String(opportunities.length)}/><Mini label="History" value={String(history.length)}/></div></Card>{ownerCloud&&<Card title="Cloud backup"><button onClick={()=>void hydrateCloud().then(()=>flash('Data cloud ditarik ulang'))} className="btn-secondary">Refresh dari Cloud</button></Card>}</div>
}

function CloudView({products,orders,restocks,customerNotes,expenses,targets,opportunities,history,audit,channelRules,suppliers,purchaseOrders,inventoryLedger,settlements,disputes,automationRules,notifications,dashboardPreferences,customerTags,cloudUser,setCloudUser,hydrateCloud,realtimeStatus,setRealtimeStatus,flash}:Ctx){
  const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [busy,setBusy]=useState(false)
  const login=async()=>{setBusy(true);try{const u=await cloudSignIn(email,password);setCloudUser(u);await hydrateCloud();flash('Cloud login berhasil')}catch(e:any){flash(e.message||'Login gagal')}finally{setBusy(false)}}
  const logout=async()=>{await cloudSignOut();setCloudUser(null);setRealtimeStatus('Offline');flash('Logout cloud')}
  const upload=async()=>{setBusy(true);try{for(const [entity,data] of [['products',products],['orders',orders],['restocks',restocks],['customer_notes',customerNotes],['expenses',expenses],['business_targets',targets],['opportunities',opportunities],['price_history',history],['audit_logs',audit],['channel_rules',channelRules],['suppliers',suppliers],['purchase_orders',purchaseOrders],['inventory_ledger',inventoryLedger],['settlements',settlements],['disputes',disputes],['automation_rules',automationRules],['notifications',notifications],['dashboard_preferences',[dashboardPreferences]],['customer_tags',customerTags]] as [string,any[]][])await syncEntity(entity,data,true);flash('Semua data lokal dikirim ke cloud')}catch(e:any){flash(e.message||'Upload gagal')}finally{setBusy(false)}}
  if(!cloudUser)return <Card title="Cloud Sync V6.4.2" subtitle="Login memakai HttpOnly cookie; token tidak lagi disimpan di localStorage."><div className="grid max-w-lg gap-3"><Field label="Email Supabase" value={email} onChange={setEmail}/><Field label="Password" type="password" value={password} onChange={setPassword}/><button disabled={busy} onClick={login} className="btn-primary">{busy?'Memproses...':'Login Cloud'}</button><p className="text-xs text-muted-foreground">Pastikan environment Supabase terisi. Untuk Payroll V6.4.2, server juga membutuhkan <code>SUPABASE_SERVICE_ROLE_KEY</code>.</p></div></Card>
  return <div className="space-y-5"><Card title="Cloud aktif"><div className="flex flex-wrap items-center justify-between gap-3"><div><strong>{cloudUser.name||cloudUser.email}</strong><p className="text-xs text-muted-foreground">Role: {cloudUser.role} · {realtimeStatus}</p></div><button onClick={logout} className="btn-secondary">Logout</button></div></Card><section className="grid gap-3 md:grid-cols-2"><button onClick={upload} disabled={busy||cloudUser.role!=='owner'} className="action-card disabled:opacity-50"><strong>↑ Migrasi lokal → cloud</strong><span>Gunakan sekali saat migrasi dari V3/local. Hanya Owner.</span></button><button onClick={()=>void hydrateCloud().then(()=>flash('Cloud → lokal selesai')).catch((e:any)=>flash(e.message))} className="action-card"><strong>↓ Cloud → lokal</strong><span>Tarik data terbaru ke cache perangkat ini.</span></button></section><Card title="Arsitektur V6.4.2"><ul className="space-y-2 text-sm text-muted-foreground"><li>• Login: server-side HttpOnly cookies.</li><li>• Order/restock/refund: PostgreSQL RPC atomic dengan row lock.</li><li>• Realtime: native WebSocket Supabase; UI memakai delta sync dan retry queue saat koneksi terputus.</li><li>• LocalStorage: cache/fallback offline; konflik update dideteksi dengan updated_at sebelum overwrite.</li></ul></Card></div>
}

function AuditView({audit}:Ctx){return <Card title="Riwayat Perubahan" subtitle="Audit aksi penting Owner dan Worker."><div className="space-y-2">{audit.map((x:AuditLog)=><div key={x.id} className="rounded-xl border p-3"><div className="flex justify-between gap-3"><strong className="text-sm">{x.action}</strong><span className="text-xs text-muted-foreground">{fmt(x.createdAt)}</span></div><p className="mt-1 text-xs text-muted-foreground">{x.actor}{x.detail?` · ${x.detail}`:''}</p></div>)}{!audit.length&&<Empty text="Belum ada audit log."/>}</div></Card>}

function DailyBars({orders,days}:{orders:Order[];days:number}){const rows=[] as {label:string;profit:number;revenue:number}[];for(let i=days-1;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=d.toISOString().slice(0,10);const list=orders.filter(o=>o.status==='Selesai'&&(o.completedAt||o.createdAt).slice(0,10)===key);rows.push({label:d.toLocaleDateString('id-ID',{day:'2-digit',month:'short'}),profit:list.reduce((s,o)=>s+o.snapshot.profit,0),revenue:list.reduce((s,o)=>s+o.snapshot.revenue,0)})}const max=Math.max(1,...rows.map(x=>Math.abs(x.profit)));return <div className="space-y-3"><div className="flex h-48 items-end gap-1 overflow-x-auto border-b pb-1">{rows.map((x,i)=><div key={`${x.label}-${i}`} className="group flex min-w-[18px] flex-1 flex-col items-center justify-end gap-1" title={`${x.label}: ${money(x.profit)}`}><span className="hidden text-[9px] font-bold group-hover:block sm:block">{days<=7?money(x.profit).replace('Rp',''):''}</span><div className={`w-full max-w-10 rounded-t ${x.profit<0?'bg-red-400':'bg-primary/80'}`} style={{height:`${Math.max(3,Math.abs(x.profit)/max*140)}px`}}/><span className="rotate-[-45deg] whitespace-nowrap text-[8px] text-muted-foreground sm:rotate-0">{days<=14?x.label:x.label.split(' ')[0]}</span></div>)}</div><p className="text-xs text-muted-foreground">Hover/tap bar untuk melihat profit. Merah berarti transaksi hari tersebut negatif.</p></div>}

function TopProducts({orders}:{orders:Order[]}){return <Card title="Produk terlaris"><RankList rows={aggregate(orders,'productName').slice(0,6)}/></Card>}
function aggregate(orders:Order[],field:'game'|'productName'){const m=new Map<string,{label:string,revenue:number,profit:number,orders:number}>();orders.filter(o=>o.status==='Selesai').forEach(o=>{const label=o[field]||'Lainnya';const x=m.get(label)||{label,revenue:0,profit:0,orders:0};x.revenue+=o.snapshot.revenue;x.profit+=o.snapshot.profit;x.orders+=1;m.set(label,x)});return [...m.values()].sort((a,b)=>b.profit-a.profit)}
function RankList({rows}:{rows:{label:string;revenue:number;profit:number;orders:number}[]}){const max=Math.max(1,...rows.map(x=>Math.max(0,x.profit)));return <div className="space-y-3">{rows.map((x,i)=><div key={x.label} className="grid grid-cols-[24px_1fr_auto] items-center gap-3"><span className="text-xs font-black text-muted-foreground">#{i+1}</span><div><div className="mb-1 flex justify-between gap-3 text-xs"><strong>{x.label}</strong><span>{x.orders} order</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{width:`${Math.max(2,Math.max(0,x.profit)/max*100)}%`}}/></div></div><div className="text-right"><strong className={x.profit>=0?'text-emerald-700':'text-red-600'}>{money(x.profit)}</strong><small className="block text-muted-foreground">{money(x.revenue)}</small></div></div>)}{!rows.length&&<Empty text="Belum ada transaksi selesai."/>}</div>}

function AlertList({items}:{items:any[]}){return <div className="space-y-2">{items.map(x=><div key={x.id} className={`rounded-xl border p-3 ${x.level==='danger'?'border-red-200 bg-red-50 dark:bg-red-950/30':x.level==='warn'?'border-amber-200 bg-amber-50 dark:bg-amber-950/30':x.level==='success'?'border-emerald-200 bg-emerald-50 dark:bg-emerald-950/30':'bg-muted/30'}`}><strong className="text-sm">{x.title}</strong><p className="mt-1 text-xs text-muted-foreground">{x.detail}</p></div>)}{!items.length&&<Empty text="Tidak ada notifikasi penting."/>}</div>}

function Brand(){return <div className="border-b p-6"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary text-sm font-black text-primary-foreground">IP</div><div><strong>Itemku Profit</strong><p className="text-[11px] text-muted-foreground">Management System V6.4.2</p></div></div></div>}
function Navigation({active,setActive,mobile=false}:{active:string;setActive:(s:string)=>void;mobile?:boolean}){return <nav className={mobile?'flex gap-2 overflow-x-auto':'space-y-5 p-3'}>{NAV.map(s=><div key={s.group} className={mobile?'shrink-0':''}>{!mobile&&<p className="px-3 pb-2 text-[10px] font-bold uppercase tracking-[.16em] text-muted-foreground">{s.group}</p>}<div className={mobile?'flex gap-1':'space-y-1'}>{s.items.map(item=><button key={item} onClick={()=>setActive(item)} className={`rounded-lg px-3 py-2 text-xs font-semibold ${active===item?'bg-primary text-primary-foreground':'text-muted-foreground hover:bg-muted hover:text-foreground'} ${mobile?'whitespace-nowrap':'w-full text-left'}`}>{item}</button>)}</div></div>)}</nav>}
function SyncPill({state,online}:{state:SyncState;online:boolean}){const label=!online?'Offline':state==='synced'?'Tersinkron':state==='pending'?'Syncing':state==='error'?'Sync gagal':'Offline';const cls=!online||state==='offline'?'bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-200':state==='synced'?'bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-200':state==='error'?'bg-red-100 text-red-700 dark:bg-red-950 dark:text-red-200':'bg-blue-100 text-blue-700 dark:bg-blue-950 dark:text-blue-200';return <span className={`hidden rounded-full px-2.5 py-1.5 text-[10px] font-bold xl:inline-flex ${cls}`}>{label}</span>}
function MobileBottomNav({active,setActive}:{active:string;setActive:(s:string)=>void}){const items=[['Home','Ringkasan'],['Order','Quick Order'],['Produk','Daftar Produk'],['Keuangan','Cash Flow'],['Lainnya','Health & Import']];return <nav className="fixed inset-x-0 bottom-0 z-40 grid grid-cols-5 border-t bg-card/95 p-1 backdrop-blur lg:hidden">{items.map(([label,target])=><button key={target} onClick={()=>setActive(target)} className={`rounded-xl px-1 py-2.5 text-[10px] font-black ${active===target?'bg-primary text-primary-foreground':'text-muted-foreground'}`}>{label}</button>)}</nav>}
function CloudPill({user,status}:{user:CloudUser|null;status:string}){return <span className={`hidden rounded-full px-2.5 py-1.5 text-[10px] font-bold sm:inline-flex ${user?'bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-200':'bg-muted text-muted-foreground'}`}>{user?`Cloud · ${status}`:'Local'}</span>}
function ThemeButton({settings,setSettings}:{settings:StoreSettings;setSettings:(s:StoreSettings)=>void}){const next=settings.theme==='system'?'dark':settings.theme==='dark'?'light':'system';return <button onClick={()=>setSettings({...settings,theme:next})} className="rounded-lg border px-3 py-2 text-xs font-bold" title="Ubah tema">{settings.theme==='dark'?'☾':settings.theme==='light'?'☀':'◐'}</button>}
function Card({title,subtitle,children,action}:{title:string;subtitle?:string;children:React.ReactNode;action?:React.ReactNode}){return <section className="rounded-2xl border bg-card p-5 shadow-sm"><div className="mb-4 flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-base font-bold">{title}</h2>{subtitle&&<p className="mt-1 max-w-3xl text-xs leading-relaxed text-muted-foreground">{subtitle}</p>}</div>{action}</div>{children}</section>}
function Metric({label,value,tone}:{label:string;value:string;tone?:'good'|'bad'|'warn'}){const c=tone==='good'?'text-emerald-700':tone==='bad'?'text-red-600':tone==='warn'?'text-amber-700':'';return <div className="rounded-xl border bg-card p-4"><span className="block text-xs text-muted-foreground">{label}</span><strong className={`mt-1 block text-xl ${c}`}>{value}</strong></div>}
function Field({label,value,onChange,placeholder,type='text'}:{label:string;value:string;onChange:(v:string)=>void;placeholder?:string;type?:string}){return <label className="grid gap-1.5 text-xs font-semibold">{label}<input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} className="input h-10"/></label>}
function Num({label,value,onChange}:{label:string;value:number;onChange:(v:number)=>void}){return <label className="grid gap-1.5 text-xs font-semibold">{label}<input type="number" min="0" value={value} onChange={e=>onChange(Math.max(0,Number(e.target.value)||0))} className="input h-10"/></label>}
function Select({label,value,onChange,options}:{label:string;value:string;onChange:(v:string)=>void;options:(string[]|readonly string[])[]}){return <label className="grid gap-1.5 text-xs font-semibold">{label}<select value={value} onChange={e=>onChange(e.target.value)} className="input h-10">{options.map((x:any)=><option key={x[0]} value={x[0]}>{x[1]}</option>)}</select></label>}
function Check({label,checked,onChange}:{label:string;checked:boolean;onChange:(v:boolean)=>void}){return <label className="flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-semibold"><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/>{label}</label>}
function Mini({label,value}:{label:string;value:string}){return <div><span className="block text-[10px] font-bold uppercase tracking-wider text-muted-foreground">{label}</span><p className="mt-1 text-sm font-semibold">{value}</p></div>}
function Status({status}:{status:OrderStatus}){const tone=status==='Selesai'?'green':status==='Refund'||status==='Cancel'?'red':status==='Diproses'?'amber':'blue';return <Badge tone={tone}>{status}</Badge>}
function Badge({children,tone='gray'}:{children:React.ReactNode;tone?:string}){const cls=tone==='green'?'bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-200':tone==='red'?'bg-red-100 text-red-700 dark:bg-red-950 dark:text-red-200':tone==='amber'?'bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-200':tone==='blue'?'bg-blue-100 text-blue-700 dark:bg-blue-950 dark:text-blue-200':'bg-muted text-muted-foreground';return <span className={`inline-flex rounded-full px-2 py-1 text-[10px] font-bold ${cls}`}>{children}</span>}
function TrendBadge({trend}:{trend:string}){return <Badge tone={trend==='naik'?'green':trend==='turun'?'red':trend==='stabil'?'blue':'gray'}>{trend==='naik'?'↑ Naik':trend==='turun'?'↓ Turun':trend==='stabil'?'→ Stabil':'Baru'}</Badge>}
function Progress({value}:{value:number}){return <div className="h-3 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{width:`${Math.max(0,Math.min(100,value))}%`}}/></div>}
function Table({headers,children}:{headers:string[];children:React.ReactNode}){return <div className="overflow-x-auto"><table className="w-full min-w-[820px] border-collapse text-left text-xs"><thead><tr>{headers.map(h=><th key={h} className="border-b px-3 py-2.5 font-semibold text-muted-foreground">{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}
function Td({children,className=''}:{children:React.ReactNode;className?:string}){return <td className={`border-b px-3 py-3 align-top ${className}`}>{children}</td>}
function Empty({text}:{text:string}){return <p className="rounded-xl border border-dashed p-8 text-center text-sm text-muted-foreground">{text}</p>}
